values
  ('yilmazabdurrah', 'Abdurrahman Yılmaz', 'Dr. Öğr. Üyesi', 'kontrol', 'Abdurrahman Yılmaz''ın araştırmaları robotics software, Digital Twin, simulation, localization ve autonomous navigation ekseninde ilerlemektedir. Son dönem çalışmalarında agricultural robotics, 3D photogrammetry, autonomous mobile robot path planning ve robot–plant interaction için Digital Twin sistemleri öne çıkmaktadır.', ARRAY['Robotics', 'Mobile Robotics', 'Digital Twin', 'Localization', 'Autonomous Navigation', 'Path Planning']::text[], ARRAY['Simulation', '3D Reconstruction', 'Photogrammetry', 'ICP', 'Machine Learning', 'Robot Perception', 'Computer Vision']::text[], ARRAY['Agricultural Robotics', 'Smart AGVs', 'Digital Agriculture', 'Autonomous Mobile Robots']::text[], 'Unity, Gazebo, ROS / ROS2, 3D Reconstruction Tools, Robot Simulation Platforms', ARRAY[]::text[], ARRAY['Gazebo/Unity tabanlı robot Digital Twin', 'Agricultural robot autonomous navigation', 'Synthetic-data generation for robotics', 'Digital Twin validation framework', '3D plant reconstruction', 'Robot–plant interaction simulation', 'Sim-to-real agricultural robotics']::text[], 'https://akademi.itu.edu.tr/yilmazabdurrah', 'https://akademi.itu.edu.tr/yilmazabdurrah', '2026-09-18'),
  ('ahmetonat', 'Ahmet Onat', 'Doç. Dr.', 'kontrol', 'Ahmet Onat''ın araştırmaları Reinforcement Learning, Networked Control ve robotic control alanlarında yoğunlaşmaktadır. Deep Q-Network, Bayesian Learning, energy optimization ve communication-aware control son dönem çalışmalarında yer almaktadır.', ARRAY['Networked Control', 'Reinforcement Learning-Based Control', 'Robotic Control']::text[], ARRAY['Deep Q-Learning', 'Bayesian Learning', 'Optimization', 'Sensor Systems']::text[], ARRAY['Fuel Cells', 'Wind Turbines', 'Underwater Vehicles', 'Robot Manipulators']::text[], null, ARRAY[]::text[], ARRAY['Deep Q-Network controller', 'AUV networked control', 'RL-based energy optimization', 'Bayesian robot trajectory control', 'Communication-aware autonomous systems']::text[], 'https://akademi.itu.edu.tr/ahmetonat', 'https://akademi.itu.edu.tr/ahmetonat', '2026-09-18'),
  ('ergenca', 'Ali Fuat Ergenç', 'Doç. Dr.', 'kontrol', 'Ali Fuat Ergenç''in araştırmaları dynamic systems modeling, control systems, industrial control, predictive maintenance ve sensing alanlarında çeşitlenmektedir.', ARRAY['Dynamic Systems Modeling', 'Control Systems', 'Time-Delay Systems', 'Industrial Control']::text[], ARRAY['Deep Learning', 'Image Processing', 'Predictive Maintenance', 'Sensor Systems', 'Data Analysis']::text[], ARRAY['Connected Vehicles', 'Biomedical Systems', 'Automotive Manufacturing', 'Hydraulic Systems', 'Engine ECUs']::text[], null, ARRAY[]::text[], ARRAY['Deep Learning based predictive maintenance', 'V2V delay-aware vehicle control', 'Industrial fault diagnosis', 'Computer Vision based industrial inspection', 'Embedded ECU control', 'Biomedical system modeling']::text[], 'https://akademi.itu.edu.tr/ergenca', 'https://akademi.itu.edu.tr/ergenca', '2026-09-18'),
  ('fhashemzadeh', 'Farzad Hashemzadeh', 'Doç. Dr.', 'kontrol', 'Farzad Hashemzadeh''in araştırmaları nonlinear systems, switched systems, hybrid systems ve networked control üzerine yoğunlaşmaktadır. Güncel çalışmalarında drone swarm coverage, hybrid electric vehicle control ve bidirectional DC-DC converters gibi uygulamalar bulunmaktadır.', ARRAY['Nonlinear Control', 'Switched Systems', 'Hybrid Systems', 'Robust Control', 'Multi-Agent Systems']::text[], ARRAY['Event-Triggered Control', 'H∞ Control', 'Teleoperation', 'Networked Control']::text[], ARRAY['Drone Swarms', 'Hybrid Electric Vehicles', 'DC-DC Converters', 'Telerobotics']::text[], null, ARRAY[]::text[], ARRAY['Drone swarm cooperative control', 'Hybrid EV converter control', 'Event-triggered multi-agent systems', 'Network-delay-tolerant teleoperation', 'Resilient switched systems']::text[], 'https://akademi.itu.edu.tr/fhashemzadeh', 'https://akademi.itu.edu.tr/fhashemzadeh', '2026-09-18'),
  ('caliskanf', 'Fikret Çalışkan', 'Prof. Dr.', 'kontrol', 'Fikret Çalışkan''ın araştırmaları aerospace control, UAV systems, fault diagnosis ve state estimation konularında yoğunlaşmaktadır. Güncel çalışmalarında quadrotor control, Sliding Mode Control, Extended Kalman Filter ve EV battery state estimation bulunmaktadır.', ARRAY['Aerospace Control', 'UAV Control', 'Sliding Mode Control', 'Fault Detection and Isolation']::text[], ARRAY['State Estimation', 'Extended Kalman Filter', 'Modeling and Simulation', 'Artificial Neural Networks']::text[], ARRAY['UAVs', 'Quadrotors', 'Electric Vehicles', 'Hybrid-Electric Aircraft']::text[], null, ARRAY[]::text[], ARRAY['UAV fault detection', 'Adaptive Sliding Mode Flight Control', 'Battery SOC estimation', 'Hybrid aircraft propulsion simulation', 'Computer Vision ile aircraft inspection', 'Fault-tolerant UAV control']::text[], 'https://akademi.itu.edu.tr/caliskanf', 'https://akademi.itu.edu.tr/caliskanf', '2026-09-18'),
  ('gulayoke', 'Gülay Öke Günel', 'Prof. Dr.', 'kontrol', 'Gülay Öke Günel''in çalışmaları Machine Learning tabanlı adaptive control, nonlinear control ve intelligent control konularını kapsamaktadır. Support Vector Regression, neural networks, LSTM, NARMA-L2 ve distributed optimization gibi yöntemler araştırmalarında kullanılmaktadır.', ARRAY['Adaptive Control', 'Nonlinear Control', 'Intelligent Control', 'Inverse Optimal Control']::text[], ARRAY['Neural Networks', 'Support Vector Regression', 'LSTM', 'Machine Learning', 'Distributed Optimization', 'NARMA-L2']::text[], ARRAY['Robotic Manipulators', 'Nonlinear Dynamical Systems', 'Human-Robot Interaction']::text[], null, ARRAY[]::text[], ARRAY['Neural adaptive control', 'LSTM self-tuning control', 'Support Vector Regression controller', 'Learning-based manipulator control', 'Distributed optimization algorithms', 'Neural inverse optimal control']::text[], 'https://akademi.itu.edu.tr/gulayoke', 'https://akademi.itu.edu.tr/gulayoke', '2026-09-18'),
  ('temeltash', 'Hakan Temeltaş', 'Prof. Dr.', 'kontrol', 'Hakan Temeltaş''ın araştırmaları robotik, otonom sistemler, mobil robotlar, SLAM, lokalizasyon, çoklu robot sistemleri ve öğrenme tabanlı robot kontrolü etrafında yoğunlaşmaktadır. Son dönem çalışmalarında Deep Reinforcement Learning, quadruped robots, industrial robot inverse kinematics, autonomous exploration ve uncertainty-aware learning gibi konular öne çıkmaktadır.', ARRAY['Robotics', 'Mobile Robotics', 'Autonomous Robotics', 'SLAM', 'Robot Localization', 'Robot Navigation', 'Deep Reinforcement Learning']::text[], ARRAY['Point Cloud Processing', 'Sensor Fusion', 'LiDAR', 'State Estimation', 'Motion Planning', 'RRT', 'Deep Learning', 'Generative AI for Motion', 'Inverse Kinematics', 'Data-Driven Modeling']::text[], ARRAY['Quadruped Robots', 'Industrial Robots', 'Autonomous Mobile Robots', 'Heterogeneous Robot Teams', 'Autonomous Exploration']::text[], null, ARRAY[]::text[], ARRAY['Deep Reinforcement Learning ile quadruped locomotion', 'Multi-Agent Deep RL ile çoklu robot koordinasyonu', 'LiDAR tabanlı autonomous exploration ve SLAM', 'Model-free RL ile industrial robot inverse kinematics', 'Sim-to-real robot learning', 'Uncertainty-aware reinforcement learning', 'Diffusion models ile robot motion generation', 'Autonomous robot recovery after falling']::text[], 'https://akademi.itu.edu.tr/temeltash', 'https://akademi.itu.edu.tr/temeltash', '2026-09-18'),
