  ('kocaarslani', 'İlhan Kocaarslan', 'Prof. Dr.', 'kontrol', 'İlhan Kocaarslan''ın çalışmaları transportation systems, automation, energy systems ve mobility technologies etrafında çeşitlenmektedir.', ARRAY['Transportation Systems', 'Automation', 'Energy Systems']::text[], ARRAY['Autonomous Systems', 'Mobility Technologies', 'Hydrogen Energy', 'System Integration']::text[], ARRAY['Hyperloop', 'Autonomous Marine Vehicles', 'Mobility Platforms']::text[], null, ARRAY[]::text[], ARRAY['Autonomous marine vehicle platform', 'Hyperloop control and simulation', 'Mobility-system digital platform', 'Energy-management software', 'Blockchain-enabled mobility infrastructure']::text[], 'https://akademi.itu.edu.tr/kocaarslani', 'https://akademi.itu.edu.tr/kocaarslani', '2026-09-18'),
  ('ustoglui', 'İlker Üstoğlu', 'Doç. Dr.', 'kontrol', 'İlker Üstoğlu''nun araştırmaları Model Predictive Control, aerospace control, autonomous navigation ve safety-critical systems konularında yoğunlaşmaktadır.', ARRAY['Model Predictive Control', 'Robust Control', 'Aerospace Control', 'Safety-Critical Control']::text[], ARRAY['Fault Detection', 'GNSS/INS Sensor Fusion', 'H∞ Control', 'Markov Models']::text[], ARRAY['Fixed-Wing Aircraft', 'Navigation Systems', 'Rail Transit']::text[], null, ARRAY[]::text[], ARRAY['MPC automatic landing', 'GNSS/INS fault detection', 'Robust autonomous navigation', 'Safety-critical control software', 'Fault-tolerant navigation systems']::text[], 'https://akademi.itu.edu.tr/ustoglui', 'https://akademi.itu.edu.tr/ustoglui', '2026-09-18'),
  ('ucakk', 'Kemal Uçak', 'Doç. Dr.', 'kontrol', 'Kemal Uçak''ın çalışmaları Machine Learning, nonlinear control, adaptive control ve system identification kesişimindedir. Güncel araştırmalarında data-driven Model Predictive Control, sparse identification ve machine learning tabanlı nonlinear control yöntemleri bulunmaktadır.', ARRAY['Nonlinear Control', 'Adaptive Control', 'Data-Driven Control', 'Model Predictive Control', 'System Identification']::text[], ARRAY['Machine Learning', 'Support Vector Machines', 'Sparse Identification', 'SINDy-Type Methods', 'Runge-Kutta Methods', 'Fuzzy Control', 'Inverse Optimal Control']::text[], ARRAY['Nonlinear Dynamical Systems', 'Intelligent Controllers', 'Data-Driven Dynamical Models']::text[], null, ARRAY[]::text[], ARRAY['Sparse Identification + MPC', 'Neural/SVM adaptive control', 'Data-driven nonlinear MPC', 'Physics-informed system identification', 'Learning-based adaptive control', 'Online system identification and control']::text[], 'https://akademi.itu.edu.tr/ucakk', 'https://akademi.itu.edu.tr/ucakk', '2026-09-18'),
  ('baradarannia', 'Mahdi Baradarannia', 'Doç. Dr.', 'kontrol', 'Mahdi Baradarannia''nın araştırmaları nonlinear control, multi-agent systems, event-triggered control, sliding-mode control ve networked control üzerine yoğunlaşmaktadır.', ARRAY['Nonlinear Control', 'Sliding Mode Control', 'Multi-Agent Systems', 'Distributed Control', 'Robust Control']::text[], ARRAY['Event-Triggered Control', 'Consensus', 'Networked Control Systems', 'Finite-Time Control', 'Adaptive Control']::text[], ARRAY['Microgrids', 'Distributed Agents', 'Networked Cyber-Physical Systems']::text[], null, ARRAY[]::text[], ARRAY['Multi-agent consensus', 'Event-triggered distributed control', 'DoS-resilient networked control', 'Model-free adaptive control', 'Distributed microgrid control', 'Fixed-time cooperative control']::text[], 'https://akademi.itu.edu.tr/baradarannia', 'https://akademi.itu.edu.tr/baradarannia', '2026-09-18'),
  ('soylemezm', 'Mehmet Turan Söylemez', 'Prof. Dr.', 'kontrol', 'Mehmet Turan Söylemez''in araştırmaları robust control, controller design, time-delay systems ve transportation control üzerine yoğunlaşmaktadır. Railway signalling, autonomous driving ve multi-agent transportation systems önemli uygulama alanlarıdır.', ARRAY['Robust Control', 'PID Control', 'Linear Control', 'Time-Delay Systems', 'Controller Design']::text[], ARRAY['Model Predictive Control', 'Disturbance Observers', 'Multi-Agent Systems', 'Optimization']::text[], ARRAY['Rail Systems', 'ADAS', 'Autonomous Driving', 'Traffic Control', 'Electric Traction']::text[], null, ARRAY[]::text[], ARRAY['Railway control and signalling', 'Robust vehicle lateral control', 'Reservation-based intersection management', 'Multi-agent traffic control', 'Robust controller design for uncertain systems', 'Disturbance-observer-based control']::text[], 'https://akademi.itu.edu.tr/soylemezm', 'https://akademi.itu.edu.tr/soylemezm', '2026-09-18'),
  ('mustafadogan', 'Mustafa Doğan', 'Prof. Dr.', 'kontrol', 'Mustafa Doğan''ın araştırmaları optimal control, robotics, sensor fusion ve aerospace systems alanlarında yoğunlaşmaktadır.', ARRAY['Optimal Control', 'Robotics Control', 'UAV Control']::text[], ARRAY['Sensor Fusion', 'SLAM', 'Output Regulation', 'State Estimation']::text[], ARRAY['Fixed-Wing UAV', 'Mobile Robots', 'Adaptive Optics']::text[], null, ARRAY[]::text[], ARRAY['Vision-based UAV trajectory tracking', 'Optimal UAV control', 'Sensor-fusion SLAM', 'Visual servoing', 'State-estimation-based robotics']::text[], 'https://akademi.itu.edu.tr/mustafadogan', 'https://akademi.itu.edu.tr/mustafadogan', '2026-09-18'),
  ('guzelkaya', 'Müjde Güzelkaya', 'Prof. Dr.', 'kontrol', 'Müjde Güzelkaya''nın çalışmalarında Intelligent Control, nonlinear control, fractional-order control ve system identification öne çıkmaktadır. Güncel araştırmalarında Federated Learning based System Identification, uncertainty quantification ve Deep Reinforcement Learning tabanlı kontrol uygulamaları bulunmaktadır.', ARRAY['Intelligent Control', 'Fractional-Order Control', 'System Identification', 'Nonlinear Control', 'Optimal Control']::text[], ARRAY['Federated Learning', 'Neural Networks', 'Reinforcement Learning', 'Extended Kalman Filter', 'Uncertainty Quantification', 'Data-Driven Modeling']::text[], ARRAY['EV Thermal Systems', 'Structural Control', 'Magnetic Levitation', 'Nonlinear Processes']::text[], null, ARRAY[]::text[], ARRAY['Federated Learning ile System Identification', 'Privacy-preserving distributed system identification', 'Deep RL for intelligent control', 'Neural nonlinear identification', 'EV thermal system modeling and control', 'Uncertainty-aware identification']::text[], 'https://akademi.itu.edu.tr/guzelkaya', 'https://akademi.itu.edu.tr/guzelkaya', '2026-09-18'),
  ('oakbati', 'Onur Akbatı', 'Dr. Öğr. Üyesi', 'kontrol', 'Mevcut resmî akademik kaynaklarda araştırma alanlarını ayrıntılı ve güvenilir biçimde sınıflandırmak için yeterli bilgi bulunmamaktadır.', ARRAY['Otomasyon', 'Otonom Sistemler', 'Kontrol Teorisi ve Uygulamaları', 'Robotik']::text[], ARRAY[]::text[], ARRAY[]::text[], null, ARRAY[]::text[], ARRAY[]::text[], 'https://akademi.itu.edu.tr/oakbati', 'https://akademi.itu.edu.tr/oakbati', '2026-09-18'),
