  ('yesiloglu', 'Sıddık Murat Yeşiloğlu', 'Dr. Öğr. Üyesi', 'kontrol', 'Sıddık Murat Yeşiloğlu''nun çalışmaları robot dynamics, multibody systems, legged robotics ve underactuated robotic systems üzerine yoğunlaşmaktadır.', ARRAY['Robot Dynamics', 'Multibody Dynamics', 'Legged Robotics', 'Underactuated Systems']::text[], ARRAY['Reinforcement Learning', 'Robot Kinematics', 'Mathematical Modeling', 'Simulation']::text[], ARRAY['Legged Robots', 'Mobile Manipulators', 'Space Manipulation']::text[], null, ARRAY[]::text[], ARRAY['RL-based legged robot locomotion', 'Dynamics-aware reinforcement learning', 'Multibody robot simulator', 'Underactuated robot control', 'Quadruped dynamics']::text[], 'https://akademi.itu.edu.tr/yesiloglu', 'https://akademi.itu.edu.tr/yesiloglu', '2026-09-18'),
